"""Actual editor-session protocol over bounded native RPC; generated bytes, no user paths."""
import sys,json,pathlib,hashlib,base64,uuid,traceback
from playwright.sync_api import sync_playwright,expect
import v536_wide_mixed as f
store=f.project/'.confectory/resources.v1.json';b=None

def api(action,success=True,**kw):return f.invoke('projectResources',dict(action=action,project=f.state()['projectId'],**kw),success)['result'].get('result')
def layout(action='load',**kw):return f.invoke('projectResourceLayout',dict(action=action,project=f.state()['projectId'],**kw))['result']['result']
def entry(name='한글 🧪.bin',data=b'generated\0\xfb\xff'):
 return dict(command=uuid.uuid4().hex,item=dict(id=uuid.uuid4().hex,name=name,type='application/octet-stream',size=len(data),hash=hashlib.sha256(data).hexdigest(),modifiedAt=0,data=base64.urlsafe_b64encode(data).decode()))
def body(extra=None):return dict(revision=api('load')['revision'],imports=[entry(),entry('두 번째.bin')],**(extra or {}))
def begin(value,target='import-many',hash=None):
 raw=json.dumps(value,ensure_ascii=False,separators=(',',':')).encode();id=uuid.uuid4().hex;args=dict(id=id,target=target,length=len(raw),hash=hash or hashlib.sha256(raw).hexdigest());reply=api('upload-begin',**args);assert reply['offset']==0;return id,raw,args

def chunks(id,raw,start=0):
 while start<len(raw):
  end=min(len(raw),start+1048576);reply=api('upload-chunk',id=id,offset=start,data=base64.urlsafe_b64encode(raw[start:end]).decode());assert reply['offset']==end;start=end
 return start

def snapshot():return store.read_bytes()if store.exists()else None
def exact(before):assert snapshot()==before;assert all((f.project/k).read_bytes()==v for k,v in f.original.items());assert not f.errors and not f.external,(f.errors,f.external)
def browser():
 global b
 f.page.locator('#workspace').click(button='right',position=dict(x=700,y=260));f.page.get_by_role('button',name='프로젝트 브라우저',exact=True).click();b=f.page.locator('.window[data-key^="browser:project:"]').last;b.locator('[data-tab=resource]').click();expect(b.locator('[data-new]')).to_be_enabled()
try:
 f.start(0)
 with sync_playwright()as p:
  expect.set_options(timeout=60000);f.browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);f.page=f.setup();f.idle();browser();f.page.locator('#chat-input').fill('전송 프로토콜과 별개인 입력');f.pending();before=snapshot();value=body();id,raw,args=begin(value);split=raw.index('한'.encode())+1;part=base64.urlsafe_b64encode(raw[:split]).decode();api('upload-chunk',id=id,offset=0,data=part);assert api('upload-begin',**args)['offset']==split;api('upload-chunk',id=id,offset=0,data=part);exact(before)
  api('upload-chunk',False,id=id,offset=0,data=base64.urlsafe_b64encode(bytes([raw[0]^1])+raw[1:split]).decode());api('upload-chunk',False,id=id,offset=len(raw),data='YQ==');api('upload-commit',False,id=id);api('upload-begin',False,**{**args,'hash':'0'*64});exact(before);chunks(id,raw,split);first=api('upload-commit',id=id);assert len(first['items'])==2;committed=snapshot();assert api('upload-commit',id=id)['replayed'];exact(committed);f.checked('actual session chunks split a UTF-8 code point, replay exactly and never write before full hash/CAS commit; changed/future/incomplete/reused intent rejected; committed replay has no extra write')
  oldid=first['selectedIds'][0];row=next(x for x in layout()['items']if x['id']==oldid);layout('delete-file',revision=layout()['revision'],command=uuid.uuid4().hex,id=oldid,hash=row['hash']);deleted=snapshot();api('upload-commit',False,id=id);exact(deleted);f.checked('completed upload rechecks durable import receipts, so replay cannot resurrect a member explicitly deleted later')
  value=body();id,raw,args=begin(value);other={**args,'id':uuid.uuid4().hex};api('upload-begin',False,**other);api('upload-cancel',id=other['id']);assert api('upload-begin',**args)['offset']==0;chunks(id,raw[:8]);api('upload-cancel',id=id);api('upload-cancel',id=id);api('upload-commit',False,id=id);exact(deleted);f.checked('one pending buffer is bounded per session; competing begin is rejected and cancellation of an unknown transfer cannot cancel the real pending intent')
  id,raw,args=begin(body(),hash='0'*64);chunks(id,raw);api('upload-commit',False,id=id);exact(deleted);api('upload-cancel',id=id)
  for target in ['save-content','prepare-import-many','layout-save-content','../../outside']:
   api('upload-begin',False,id=uuid.uuid4().hex,target=target,length=1,hash='0'*64)
  api('upload-begin',False,id=uuid.uuid4().hex,target='import-many',length=6000001,hash='0'*64)
  id,raw,args=begin(body({'plan':{'writes':[{'path':'../outside','text':'never'}]}}));chunks(id,raw);api('upload-commit',False,id=id);api('upload-cancel',id=id);exact(deleted);f.checked('full-body hash, memory ceiling, strict import-only targets and existing exact fields reject tampered input and arbitrary plans without any stored data/source changes')
  id,raw,args=begin(body());chunks(id,raw);peer=entry('peer.bin');api('import',revision=api('load')['revision'],**peer);changed=snapshot();api('upload-commit',False,id=id);api('upload-commit',False,id=id);exact(changed);api('upload-cancel',id=id);f.checked('another real writer after staging makes the original final CAS fail repeatedly; transfer retry never rebases or overwrites the peer')
  id,raw,args=begin(body());chunks(id,raw[:4]);f.invoke('projectResources',dict(action='upload-chunk',project=uuid.uuid4().hex,id=id,offset=4,data='YQ=='),False);exact(changed);f.pending();state=json.dumps(f.state()['presentation']);assert id not in state and base64.urlsafe_b64encode(raw).decode()not in state;listing=f.state()['listingId'];f.page.locator('#title').click();f.page.get_by_role('button',name='프로젝트 나가기',exact=True).click();expect(f.page.locator('.home-grid')).to_be_visible();f.page.locator('[data-enter="'+listing+'"]').click();f.idle();api('upload-commit',False,id=id);assert api('upload-begin',**args)['offset']==0;api('upload-cancel',id=id);exact(changed);f.checked('actual Home/context transition retires only volatile upload state; foreign project IDs are rejected and transfer bytes/ID never enter private presentation')
  id,raw,args=begin(body());chunks(id,raw[:5]);f.pending();f.page.close();f.stop();f.start(1);f.page=f.setup();f.idle();api('upload-commit',False,id=id);assert api('upload-begin',**args)['offset']==0;api('upload-cancel',id=id);exact(changed);f.checked('cold engine restores confirmed v1 copies only; an incomplete upload is absent and explicit new staging starts at zero')
  expect(f.page.locator('#chat-input')).to_have_value('전송 프로토콜과 별개인 입력');f.browser.close()
except Exception as e:
 (f.case/'failure.json').write_text(json.dumps(dict(error=repr(e),traceback=traceback.format_exc()),ensure_ascii=False));raise
finally:
 f.stop();(f.case/'checks.json').write_text(json.dumps(f.checks,ensure_ascii=False,indent=2));(f.case/'traffic.json').write_text(json.dumps(f.traffic,ensure_ascii=False,indent=2))
print('RESOURCE_TRANSFER_API',f.case,flush=True)
